{
  "id": "p_000",
  "summary": "Diseño de API REST minimalista para gestión de tareas con operaciones CRUD, esquemas JSON y manejo de errores.",
  "approach": "Se define un objeto JSON que actúa como especificación de la API. Incluye los endpoints estándar (GET, POST, PUT, DELETE) sobre el recurso /tasks, los esquemas de datos para Task, TaskCreate, TaskUpdate y Error, respetando los principios REST y la restricción de minimalismo.",
  "tradeoffs": [
    "Al omitir paginación y filtros, la API es simple pero no escala bien para miles de tareas.",
    "El uso de PUT en lugar de PATCH obliga a enviar el recurso completo o manejar nulos explícitamente, pero simplifica la implementación."
  ],
  "evidence": [
    "Los principios REST dictan el uso de sustantivos para recursos (/tasks) y verbos HTTP para acciones.",
    "El formato de error estándar envuelve el mensaje en un objeto 'error' para facilitar el parseo en clientes frontend."
  ],
  "artifacts": [
    {
      "kind": "api_spec.json",
      "language": "json",
      "source": "{
  "api_name": "Task Management API",
  "version": "1.0.0",
  "base_url": "/api/v1",
  "endpoints": [
    {
      "method": "GET",
      "path": "/tasks",
      "description": "List all tasks",
      "request": null,
      "response": {
        "status": 200,
        "schema": {
          "type": "array",
          "items": { "$ref": "#/schemas/Task" }
        }
      }
    },
    {
      "method": "POST",
      "path": "/tasks",
      "description": "Create a new task",
      "request": {
        "body": { "$ref": "#/schemas/TaskCreate" }
      },
      "response": {
        "status": 201,
        "schema": { "$ref": "#/schemas/Task" }
      }
    },
    {
      "method": "GET",
      "path": "/tasks/{id}",
      "description": "Get a specific task",
      "request": {
        "path_params": { "id": "string" }
      },
      "response": {
        "status": 200,
        "schema": { "$ref": "#/schemas/Task" }
      }
    },
    {
      "method": "PUT",
      "path": "/tasks/{id}",
      "description": "Update a task",
      "request": {
        "path_params": { "id": "string" },
        "body": { "$ref": "#/schemas/TaskUpdate" }
      },
      "response": {
        "status": 200,
        "schema": { "$ref": "#/schemas/Task" }
      }
    },
    {
      "method": "DELETE",
      "path": "/tasks/{id}",
      "description": "Delete a task",
      "request": {
        "path_params": { "id": "string" }
      },
      "response": {
        "status": 204,
        "schema": null
      }
    }
  ],
  "schemas": {
    "Task": {
      "type": "object",
      "properties": {
        "id": { "type": "string", "format": "uuid" },
        "title": { "type": "string" },
        "description": { "type": "string" },
        "status": { "type": "string", "enum": ["pending", "in_progress", "completed"] },
        "created_at": { "type": "string", "format": "date-time" }
      },
      "required": ["id", "title", "status", "created_at"]
    },
    "TaskCreate": {
      "type": "object",
      "properties": {
        "title": { "type": "string" },
        "description": { "type": "string" },
        "status": { "type": "string", "enum": ["pending", "in_progress", "completed"] }
      },
      "required": ["title"]
    },
    "TaskUpdate": {
      "type": "object",
      "properties": {
        "title": { "type": "string" },
        "description": { "type": "string" },
        "status": { "type": "string", "enum": ["pending", "in_progress", "completed"] }
      }
    },
    "Error": {
      "type": "object",
      "properties": {
        "error": {
          "type": "object",
          "properties": {
            "code": { "type": "string" },
            "message": { "type": "string" },
            "details": { "type": "array", "items": { "type": "string" } }
          },
          "required": ["code", "message"]
        }
      }
    }
  }
}"
    }
  ]
}
